public class Main {
    public static void main(String[] args) {
        final int PASSING_MARKS = 40;
        int studentMarks = 55;
        boolean isPassed = studentMarks >= PASSING_MARKS;
        System.out.println("Scored: " + studentMarks + " / Pass Cutoff: " + PASSING_MARKS + " | Passed: " + isPassed);
    }
}

practiceProblems.description:
Declare three constants following Java standard naming:
• final int DAYS_IN_WEEK = 7;
• final int HOURS_IN_DAY = 24;
• final int TOTAL_HOURS = DAYS_IN_WEEK * HOURS_IN_DAY;
Print TOTAL_HOURS.

practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        final int DAYS_IN_WEEK = 7;
        final int HOURS_IN_DAY = 24;
        final int TOTAL_HOURS = DAYS_IN_WEEK * HOURS_IN_DAY;
        System.out.println("Hours in a Week: " + TOTAL_HOURS);
    }
}

public class Main {
    public static void main(String[] args) {
        final int MAX_USERS;
        MAX_USERS = 100;
        System.out.println("Max Users Locked: " + MAX_USERS);
    }
}

public class Main {
    public static void main(String[] args) {
        final double CONVENIENCE_FEE_RATE = 0.05;
        double ticket = 800.0;
        double fee = ticket * CONVENIENCE_FEE_RATE;
        double total = ticket + fee;
        System.out.println("Ticket: Rs " + ticket + " | Fee: Rs " + fee + " | Total: Rs " + total);
    }
}
